(()=>{'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current='login',options={},revision=0;
async function request(action,body){let r=await fetch('/api/auth/'+action,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let b=await r.json();if(!r.ok)throw Error(b.error||'요청에 실패했어요.');return b}
async function enterService(){
 const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});
 if(!response.ok)throw Error('로그인 상태를 확인하지 못했어요. 다시 시도해주세요.');
 const session=await response.json();
 if(session.mfaRequired){showMfa();return}
 if(!session.member||!session.user?.id)throw Error('로그인 세션을 유지하지 못했어요. 브라우저의 쿠키 허용 설정을 확인하고 다시 로그인해주세요.');
 let saved;try{saved=sessionStorage.getItem('muse-return-route')}catch{}
 const valid=value=>typeof value==='string'&&/^#(?:home|explore|friends|intro|profile|about|board|messages|notifications|saved|admin)(?:\/[^?#\s]*)?$/.test(value);
 const destination=valid(saved)?saved:valid(location.hash)?location.hash:'#home';
 try{sessionStorage.removeItem('muse-return-route')}catch{}
 // A fragment-only replace does not rerun the anonymous boot that stopped app.js.
 window.history.replaceState(null,'','/'+destination);
 location.reload();
}
const field=(label,id,attrs)=>'<label>'+label+'<input id="'+id+'" '+attrs+' required></label>';
function recovery(code,onContinue){++revision;let gate=document.getElementById('authGate');gate.hidden=false;document.body.classList.add('auth-checking');gate.innerHTML='<a class="logo">muse<span>.</span></a><h1>복구 코드를 보관해주세요.</h1><p>이메일과 전화번호 없이 계정을 되찾는 유일한 수단이에요.<br>이 코드는 한 번만 표시되고 사용하면 새 코드로 교체돼요.</p><code class="recovery-code">'+esc(code)+'</code><div class="auth-actions"><button id="copyRecovery">코드 복사</button><button id="downloadRecovery">파일로 보관</button></div><label class="setting-check"><input type="checkbox" id="savedRecovery"> 안전한 곳에 보관했어요.</label><button class="primary" id="continueAuth" disabled>내 공간으로</button>';document.getElementById('copyRecovery').onclick=()=>navigator.clipboard.writeText(code).then(()=>document.getElementById('copyRecovery').textContent='복사했어요').catch(()=>document.getElementById('copyRecovery').textContent='코드를 직접 복사해주세요');document.getElementById('downloadRecovery').onclick=()=>{let a=document.createElement('a'),url=URL.createObjectURL(new Blob(['MUSE 계정 복구 코드\n'+code+'\n다른 사람과 공유하지 마세요.\n'],{type:'text/plain'}));a.href=url;a.download='muse-recovery-code.txt';a.click();URL.revokeObjectURL(url)};document.getElementById('savedRecovery').onchange=e=>document.getElementById('continueAuth').disabled=!e.target.checked;document.getElementById('continueAuth').onclick=async()=>{let button=document.getElementById('continueAuth');button.disabled=true;try{await onContinue()}catch(err){let message=document.getElementById('authTransitionError');if(!message){message=document.createElement('p');message.id='authTransitionError';message.setAttribute('role','alert');gate.append(message)}message.textContent=err.message;button.disabled=false}}}
async function show(b={}){if(b.mfaRequired){showMfa();return}let ticket=++revision;document.body.classList.add('auth-checking');let gate=document.getElementById('authGate');gate.hidden=false;try{options=await request('options')}catch{}if(ticket!==revision)return;draw(b.reason||b.error||'')}
function draw(reason=''){let gate=document.getElementById('authGate'),signup=current==='register'||current==='migrate',recover=current==='recover',legacy=current==='migrate'?options.legacy:null;gate.innerHTML='<a class="logo">muse<span>.</span></a><span class="beta-pill">EVERYONE IS A MUSEUM</span><h1>'+(signup?'당신만의 세계를 열어요.':recover?'계정을 다시 만나요.':'다시 만나서 반가워요.')+'</h1><p>'+(recover?'가입 때 보관한 복구 코드로 비밀번호를 바꿀 수 있어요.':'사진 한 장, 문장 하나.<br>취향이 모이는 나의 전시관.')+'</p><div class="auth-tabs"><button id="authLogin" class="'+(current==='login'?'active':'')+'">로그인</button><button id="authRegister" class="'+(signup?'active':'')+'">회원가입</button></div><form id="nativeForm">'+field('아이디','nativeHandle','autocomplete="username" minlength="3" maxlength="24" pattern="[a-z][a-z0-9_.]{2,23}" value="'+esc(legacy?.handle||'')+'"')+(signup?'<small>소문자로 시작 · 영문 소문자·숫자·_·. · 3~24자</small><small id="handleAvailability" aria-live="polite"></small>':'')+(recover?field('일회용 복구 코드','nativeRecovery','autocomplete="off" maxlength="64" pattern="[a-f0-9]{64}"'):'')+field(recover?'새 비밀번호':'비밀번호','nativePassword','type="password" autocomplete="'+(signup||recover?'new-password':'current-password')+'" '+(signup||recover?'minlength="8" ':'')+'maxlength="128"')+(signup||recover?field('비밀번호 확인','nativeConfirm','type="password" autocomplete="new-password" minlength="8" maxlength="128"')+'<small>8~128자 · 다른 서비스와 다른 비밀번호를 사용하세요.</small>':'')+(signup?field('개인식별번호 설정 (친구 추가 할 때 사용해요)','nativeCode','inputmode="numeric" autocomplete="off" minlength="8" maxlength="8" pattern="[0-9]{8}" value="'+esc(legacy?.code||'')+'"')+'<small id="codeAvailability" aria-live="polite"># 뒤 숫자 8자리 · 검색용 공개 번호이며 로그인에 쓰이지 않아요.</small><p class="auth-fine">이메일·전화번호를 받지 않아요. 복구 코드를 잃으면 계정 복구가 어려울 수 있어요.</p><label class="setting-check"><input id="nativeAgree" type="checkbox" required> 개인정보 처리 안내를 읽고 동의해요.</label><button type="button" id="nativePrivacy">개인정보 처리 안내</button>':'')+'<button class="primary" type="submit">'+(signup?'내 전시관 만들기':recover?'비밀번호 재설정':'로그인')+'</button><p id="nativeError" role="alert">'+esc(reason)+'</p></form>'+(current==='login'?'<button class="text-button" id="recoverAccount">비밀번호를 잊었나요?</button>':'')+(options.legacy&&current!=='migrate'?'<button id="migrateAccount">기존 전시관을 MUSE 계정으로 이어오기</button>':'')+'<small>ChatGPT 계정 없이 MUSE 계정으로 이용해요.</small>';
let $=id=>document.getElementById(id);$('authLogin').onclick=()=>{current='login';draw()};$('authRegister').onclick=()=>{current='register';draw()};if($('recoverAccount'))$('recoverAccount').onclick=()=>{current='recover';draw()};if($('migrateAccount'))$('migrateAccount').onclick=()=>{current='migrate';draw()};if($('nativePrivacy'))$('nativePrivacy').onclick=()=>window.MuseBeta.privacy();let availabilityTimer;let check=()=>{clearTimeout(availabilityTimer);let h=$('nativeHandle').value,c=$('nativeCode')?.value;availabilityTimer=setTimeout(async()=>{try{let result=await request('available?handle='+encodeURIComponent(h)+'&code='+encodeURIComponent(c||''));if($('nativeHandle')?.value!==h||$('nativeCode')?.value!==c)return;$('handleAvailability').textContent=legacy?.handle===h?'현재 계정 아이디예요.':result.handle?'사용할 수 있는 아이디예요.':'형식이 맞지 않거나 사용 중인 아이디예요.';$('codeAvailability').textContent=legacy?.code===c?'현재 계정 번호예요.':result.code?'사용할 수 있는 번호예요.':'숫자 8자리를 확인하거나 다른 번호를 선택해주세요.'}catch{}},350)};if(signup){$('nativeHandle').oninput=check;$('nativeCode').oninput=check}
$('nativeForm').onsubmit=async e=>{e.preventDefault();let btn=e.target.querySelector('[type=submit]');btn.disabled=true;$('nativeError').textContent='';try{let result=await request(current,{handle:$('nativeHandle').value,password:$('nativePassword').value,confirm:$('nativeConfirm')?.value,code:$('nativeCode')?.value,recoveryCode:$('nativeRecovery')?.value,agree:$('nativeAgree')?.checked,privacyVersion:'2026-11-10-v1'});if(result.recoveryCode)recovery(result.recoveryCode,enterService);else await enterService()}catch(err){$('nativeError').textContent=err.message;btn.disabled=false}}}
function showMfa(){++revision;let gate=document.getElementById('authGate');gate.hidden=false;document.body.classList.add('auth-checking');gate.innerHTML='<a class="logo">muse<span>.</span></a><h1>관리자 추가 인증</h1><p>등록한 인증 앱의 6자리 코드를 입력해주세요.</p><form id="adminMfaForm">'+field('인증 앱 코드','adminMfaCode','inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"')+'<button class="primary" type="submit">인증하고 계속</button><p id="adminMfaError" role="alert"></p></form><button id="cancelAdminMfa">다른 계정으로 로그인</button>';document.getElementById('adminMfaForm').onsubmit=async e=>{e.preventDefault();let button=e.target.querySelector('button');button.disabled=true;try{await request('admin-mfa',{code:document.getElementById('adminMfaCode').value});await enterService()}catch(err){document.getElementById('adminMfaError').textContent=err.message;button.disabled=false}};document.getElementById('cancelAdminMfa').onclick=async()=>{await request('logout',{});location.reload()}}
function adminReauth(onDone){openDialog('관리 작업 재인증','<p>비밀번호와 인증 앱의 새 코드를 확인하면 5분 동안 관리 작업을 실행할 수 있어요.</p><form id="adminReauthForm">'+field('비밀번호','adminReauthPassword','type="password" autocomplete="current-password" maxlength="128"')+field('인증 앱 코드','adminReauthCode','inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"')+'<button class="primary" type="submit">관리 작업 잠금 해제</button><p id="adminReauthError" role="alert"></p></form>',()=>{document.getElementById('adminReauthForm').onsubmit=async e=>{e.preventDefault();let button=e.target.querySelector('button');button.disabled=true;try{await request('admin-reauth',{password:document.getElementById('adminReauthPassword').value,code:document.getElementById('adminReauthCode').value});document.getElementById('dialog').close();onDone?.()}catch(err){document.getElementById('adminReauthError').textContent=err.message;button.disabled=false}finally{let pw=document.getElementById('adminReauthPassword');if(pw)pw.value=''}}})}
function password(){let $=id=>document.getElementById(id);openDialog('비밀번호 변경', '<p>변경하면 다른 기기의 모든 세션과 기존 복구 코드가 종료돼요.</p><form id="passwordChange">'+field('현재 비밀번호','currentPassword','type="password" autocomplete="current-password" maxlength="128"')+field('새 비밀번호','newPassword','type="password" minlength="8" maxlength="128" autocomplete="new-password"')+field('새 비밀번호 확인','confirmPassword','type="password" minlength="8" maxlength="128" autocomplete="new-password"')+'<button class="primary">변경하기</button><p id="passwordError" role="alert"></p></form>',()=>{$('passwordChange').onsubmit=async e=>{e.preventDefault();let btn=e.target.querySelector('button');btn.disabled=true;try{let r=await request('password',{current:$('currentPassword').value,password:$('newPassword').value,confirm:$('confirmPassword').value});$('dialog').close();window.MuseBeta.lock('비밀번호를 변경했어요.');recovery(r.recoveryCode,enterService)}catch(err){$('passwordError').textContent=err.message;btn.disabled=false}}})}
window.MuseAuth={show,request,password,adminReauth};
})();
